R_Trigger(CLK := g_bF050Home );

(*回零,F轴到0刻度*)
IF R_Trigger.Q THEN
  g_bF050Home := false; 
  g_boFHomeDone := false;
  nState:=40;     
END_IF;
(*使用高电平触发*)
IF g_bMnualAnalogEnable AND nState =0 THEN  (*手动触发调焦*)
  dFPosFb := g_dMnualAnalogPosition + g_fFocusShiftValue;
  dFPosFb2 := g_dMnualAnalogPosition;
  g_bMnualAnalogEnable := FALSE;
  nState:=10; 
ELSIF g_bAnalogEnable AND nState =0  THEN  (*模拟量自动调焦*)
  dFPosFb := g_dAnalogPosition + g_fFocusShiftValue;
  dFPosFb2 := g_dAnalogPosition;
  g_bAnalogEnable:=FALSE;
  g_bFocusEnable := FALSE;
  nState:=10; 
ELSIF g_bPreFocusEnable AND nState = 0 THEN  (*预调焦*)
  dFPosFb := g_dZoomPosition + g_fFocusShiftValue;
  dFPosFb2 := g_dZoomPosition;
  g_bPreFocusEnable:=FALSE;
  nState:=50; 
ELSIF bFocusShiftfEnable AND nState = 0 THEN (*焦漂补偿优先级比调焦低*)
  dFPosFb := dFPosFb2 + g_fFocusShiftValue;
  bFocusShiftfEnable := FALSE;
  bFocusShiftfEnablelag := TRUE;
  nState := 10;
END_IF;  

(*切割时=500或激光打点,当焦漂超过设定值时,进行焦漂补偿*)
IF ABS(dFPosFb2 + g_fFocusShiftValue - dFPosFb) > g_fFocusShiftValueHMI AND 
  g_fFocusShiftEnable THEN  
  bFocusShiftfEnable := TRUE;
END_IF;

CASE nState OF
  0:
  nState:=0;
  10:(*调焦电压*)
    TON_VoltageEnable(IN:=FALSE); 
    TON1(IN:=FALSE); 
    FocusTon(IN := FALSE);
    IF g_bCheckFocusDA THEN (*开启焦点矫正*)
      g_noVoltageValue :=0;(*FUN_FocusCailbration(g_FocusDAOutputArr, g_FocusDAGroupNum, dFPosFb);*)
    ELSE  
      IF dFPosFb >= dMinPosition AND dFPosFb < 0.0 THEN
        IF dMinPosition > -0.01 AND dMinPosition < 0.01 THEN
          return;
        ELSE
          dSlope := dMaxVoltage - dZeroPositionVoltage;
          dSlope := dSlope / dMinPosition;
          dIntercept := dZeroPositionVoltage;
          dVoltage :=  dSlope * dFPosFb + dIntercept;
        END_IF;
      ELSIF dFPosFb >= 0.0 AND dFPosFb <= dMaxPosition THEN
        IF dMaxPosition > -0.01 AND dMaxPosition < 0.01 THEN
          return;
        ELSE
          dSlope := dMinVoltage - dZeroPositionVoltage;
          dSlope := dSlope / dMaxPosition;
          dIntercept := dZeroPositionVoltage;
          dVoltage :=  dSlope * dFPosFb + dIntercept;
        END_IF;
      END_IF;                   
      g_noVoltageValue := FUN_FAxisVoltageToAnalog(dVoltage);
    END_IF;
    IF dFPosFbLast = dFPosFb THEN (*焦点不变,焦点完成信号提前给,延时缩短*)
      g_bFocusDone := TRUE;
      nState:=30; 
    ELSIF bFocusShiftfEnablelag THEN  (*焦漂补偿,焦点完成信号不给,延时缩短*)
      bFocusShiftfEnablelag := FALSE;
      nState:=30;
    ELSE
      nState:=15; 
    END_IF;  
  15: (*调焦电压发出稳定延时后发调焦使能*)   
    TON_VoltageEnable(IN:=TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(g_dFocusAoTime)));
    IF TON_VoltageEnable.Q THEN
      g_boVoltageEnable := TRUE;
      TON_VoltageEnable(IN:=FALSE);
      nState:=20;
    END_IF;
  20:(*调焦使能延时，关闭调焦使能*)
    TON1(IN:=TRUE,PT:=LREAL_TO_TIME(FUN_MStoS(g_dFocusEnableTime)));
    IF TON1.Q THEN
      g_boVoltageEnable := false;
      TON1(IN:=FALSE);
      nState:=25;
    END_IF; 
  25:(*焦点到位*)
    IF g_bUseVoltageArrivalSignal THEN
      IF g_biVoltageArrival THEN
        g_bFocusDone := TRUE;
        nState:=0;
      END_IF;
    ELSE
      g_bFocusDone := TRUE;
      nState:=0; 
    END_IF;
    FocusTon(IN := TRUE,PT := T#5s);
    IF FocusTon.Q THEN  (*调焦超时报警*)
      FocusTon.IN := FALSE;
      g_bFocusOvertimeAlarm := TRUE;
      nState := 0;
    END_IF;
  30: (*调焦电压发出稳定延时后发调焦使能*)
    TON_VoltageEnable(IN:=TRUE,PT:= T#10ms);
    IF TON_VoltageEnable.Q THEN
      g_boVoltageEnable := TRUE;
      TON_VoltageEnable(IN:=FALSE);
      nState:=35;
    END_IF;
  35:(*调焦使能延时，关闭调焦使能*)
    TON1(IN:=TRUE,PT:=T#50ms);
    IF TON1.Q THEN
      g_boVoltageEnable := false;      
      TON1(IN:=FALSE);
      nState:=0;
    END_IF; 
  40:(*回零信号输出*)
    TON1(IN:=FALSE);
    g_boPresterHome := TRUE;
    nState := 42; 
  42:
    TON1(IN:=TRUE,PT:= LREAL_TO_TIME(FUN_MStoS(g_dFocusHomeTime)));
    IF TON1.Q THEN          
      g_boPresterHome := FALSE;
      TON1(IN:=FALSE);
      nState := 45;
    END_IF;
  45:(*走到焦点0*)
    dFPosFb := 0.0;
    g_boFHomeDone := TRUE;
    nState := 10;
  50:(*调焦电压*)
    TON_VoltageEnable(IN:=FALSE); 
    TON1(IN:=FALSE); 
    FocusTon(IN := FALSE);
    IF g_bCheckFocusDA THEN (*开启焦点矫正*)
      g_noVoltageValue :=0;(*FUN_FocusCailbration(g_FocusDAOutputArr, g_FocusDAGroupNum, dFPosFb);*)
    ELSE  
      IF dFPosFb >= dMinPosition AND dFPosFb < 0.0 THEN
        IF dMinPosition > -0.01 AND dMinPosition < 0.01 THEN
          return;
        ELSE
          dSlope := dMaxVoltage - dZeroPositionVoltage;
          dSlope := dSlope / dMinPosition;
          dIntercept := dZeroPositionVoltage;
          dVoltage :=  dSlope * dFPosFb + dIntercept;
        END_IF;
      ELSIF dFPosFb >= 0.0 AND dFPosFb <= dMaxPosition THEN
        IF dMaxPosition > -0.01 AND dMaxPosition < 0.01 THEN
          return;
        ELSE
          dSlope := dMinVoltage - dZeroPositionVoltage;
          dSlope := dSlope / dMaxPosition;
          dIntercept := dZeroPositionVoltage;
          dVoltage :=  dSlope * dFPosFb + dIntercept;
        END_IF;
      END_IF;                   
      g_noVoltageValue := FUN_FAxisVoltageToAnalog(dVoltage);
    END_IF;
    nState := 30;
END_CASE;

(*坐标反馈*)
g_dFaxisAnoagePosFb := dFPosFb;
(*BS06K与普雷头共用报警信号*)  
ToFAlarm220(IN := g_bFilterAnalogCutAheadAlarm, PT := T#1s);
IF ToFAlarm220.Q  THEN
  IF g_bCloseCutAheadAlarm THEN
    g_Alarm.alarmArray[638] := 0;  
  ELSE
    g_Alarm.alarmArray[638] := 1333; 
  END_IF; 
ELSE
  g_Alarm.alarmArray[638] := 0;  
END_IF;
dFPosFbLast := dFPosFb;
